package com.bbu.ibot.service;

import com.bbu.ibot.model.vo.KnowledgeBaseIngestionSummary;
import com.bbu.ibot.model.vo.KnowledgeDocumentProfile;
import com.bbu.ibot.service.impl.PineconeKnowledgeIngestionServiceImpl;
import com.bbu.ibot.store.PineconeEmbeddingStoreFactory;
import dev.langchain4j.data.embedding.Embedding;
import dev.langchain4j.data.segment.TextSegment;
import dev.langchain4j.model.embedding.EmbeddingModel;
import dev.langchain4j.model.output.Response;
import dev.langchain4j.store.embedding.EmbeddingSearchRequest;
import dev.langchain4j.store.embedding.EmbeddingSearchResult;
import dev.langchain4j.store.embedding.EmbeddingStore;
import org.apache.poi.xslf.usermodel.XMLSlideShow;
import org.apache.poi.xslf.usermodel.XSLFSlide;
import org.apache.poi.xslf.usermodel.XSLFTextBox;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.PDPageContentStream;
import org.apache.pdfbox.pdmodel.font.Standard14Fonts;
import org.apache.pdfbox.pdmodel.font.PDType1Font;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.web.server.ResponseStatusException;

import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Base64;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class PineconeKnowledgeIngestionServiceImplTest {

    private static final String SIMPLE_DOC_BASE64 =
            "";

    @TempDir
    Path tempDir;

    @Test
    void shouldInspectAndIngestTextDocument() throws Exception {
        Path file = tempDir.resolve("handbook.txt");
        Files.writeString(file, "RAG helps answer with company knowledge. This sentence ensures chunking has content.");

        CapturingEmbeddingStore store = new CapturingEmbeddingStore();
        KnowledgeIngestionService service = new PineconeKnowledgeIngestionServiceImpl(
                new FakeEmbeddingModel(),
                namespace -> store);

        KnowledgeDocumentProfile preview = service.inspectDocument("enterprise", file);
        KnowledgeDocumentProfile ingested = service.ingestDocument("enterprise", file);

        assertEquals("enterprise", preview.namespace());
        assertEquals(preview.chunkCount(), ingested.chunkCount());
        assertEquals("PINECONE_INGESTED", ingested.indexingStatus());
        assertEquals(ingested.chunkCount(), store.embeddedSegments.size());
    }

    @Test
    void shouldRebuildNamespaceByClearingAndReinsertingDocuments() throws Exception {
        Path fileA = tempDir.resolve("a.txt");
        Path fileB = tempDir.resolve("b.md");
        Files.writeString(fileA, "Alpha handbook content");
        Files.writeString(fileB, "Beta handbook content");

        CapturingEmbeddingStore store = new CapturingEmbeddingStore();
        KnowledgeIngestionService service = new PineconeKnowledgeIngestionServiceImpl(
                new FakeEmbeddingModel(),
                namespace -> store);

        KnowledgeBaseIngestionSummary summary = service.rebuildKnowledgeBase("enterprise", List.of(fileA, fileB));

        assertEquals("enterprise", summary.namespace());
        assertEquals("PINECONE_REBUILT", summary.indexingStatus());
        assertEquals(1, store.removeAllCount);
        assertEquals(summary.chunkCount(), store.embeddedSegments.size());
    }

    @Test
    void shouldRejectUnsupportedFileType() throws Exception {
        Path file = tempDir.resolve("manual.xlsx");
        Files.writeString(file, "xlsx placeholder");

        KnowledgeIngestionService service = new PineconeKnowledgeIngestionServiceImpl(
                new FakeEmbeddingModel(),
                namespace -> new CapturingEmbeddingStore());

        assertThrows(ResponseStatusException.class, () -> service.inspectDocument("enterprise", file));
    }

    @Test
    void shouldInspectPdfDocument() throws Exception {
        Path file = tempDir.resolve("guide.pdf");
        createPdf(file, "Company policy for retrieval augmented generation.");

        CapturingEmbeddingStore store = new CapturingEmbeddingStore();
        KnowledgeIngestionService service = new PineconeKnowledgeIngestionServiceImpl(
                new FakeEmbeddingModel(),
                namespace -> store);

        KnowledgeDocumentProfile profile = service.inspectDocument("enterprise", file);

        assertEquals("enterprise", profile.namespace());
        assertTrue(profile.chunkCount() > 0);
    }

    @Test
    void shouldIngestDocxDocument() throws Exception {
        Path file = tempDir.resolve("guide.docx");
        createDocx(file, "Internal SOP for enterprise search.");

        CapturingEmbeddingStore store = new CapturingEmbeddingStore();
        KnowledgeIngestionService service = new PineconeKnowledgeIngestionServiceImpl(
                new FakeEmbeddingModel(),
                namespace -> store);

        KnowledgeDocumentProfile profile = service.ingestDocument("enterprise", file);

        assertEquals("PINECONE_INGESTED", profile.indexingStatus());
        assertTrue(store.embeddedSegments.stream().anyMatch(segment -> segment.text().contains("Internal SOP")));
    }

    @Test
    void shouldIngestDocDocument() throws Exception {
        Path file = tempDir.resolve("legacy-guide.doc");
        createDoc(file);

        CapturingEmbeddingStore store = new CapturingEmbeddingStore();
        KnowledgeIngestionService service = new PineconeKnowledgeIngestionServiceImpl(
                new FakeEmbeddingModel(),
                namespace -> store);

        KnowledgeDocumentProfile profile = service.ingestDocument("enterprise", file);

        assertEquals("PINECONE_INGESTED", profile.indexingStatus());
        assertTrue(store.embeddedSegments.stream().anyMatch(segment -> segment.text().contains("This is a simple file created with Word 97-SR2")));
    }

    @Test
    void shouldInspectPptxDocument() throws Exception {
        Path file = tempDir.resolve("briefing.pptx");
        createPptx(file, "Quarterly search update", "RAG rollout for enterprise teams.");

        CapturingEmbeddingStore store = new CapturingEmbeddingStore();
        KnowledgeIngestionService service = new PineconeKnowledgeIngestionServiceImpl(
                new FakeEmbeddingModel(),
                namespace -> store);

        KnowledgeDocumentProfile profile = service.inspectDocument("enterprise", file);

        assertEquals("enterprise", profile.namespace());
        assertTrue(profile.chunkCount() > 0);
    }

    private static class FakeEmbeddingModel implements EmbeddingModel {

        @Override
        public Response<List<Embedding>> embedAll(List<TextSegment> textSegments) {
            List<Embedding> embeddings = new ArrayList<>();
            for (TextSegment ignored : textSegments) {
                embeddings.add(Embedding.from(new float[]{1.0f, 2.0f, 3.0f}));
            }
            return Response.from(embeddings);
        }
    }

    private static class CapturingEmbeddingStore implements EmbeddingStore<TextSegment> {

        private final List<TextSegment> embeddedSegments = new ArrayList<>();
        private int removeAllCount;

        @Override
        public String add(Embedding embedding) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void add(String id, Embedding embedding) {
            throw new UnsupportedOperationException();
        }

        @Override
        public String add(Embedding embedding, TextSegment embedded) {
            throw new UnsupportedOperationException();
        }

        @Override
        public List<String> addAll(List<Embedding> embeddings) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void addAll(List<String> ids, List<Embedding> embeddings, List<TextSegment> embedded) {
            embeddedSegments.addAll(embedded);
        }

        @Override
        public void removeAll(Collection<String> ids) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void removeAll() {
            removeAllCount++;
            embeddedSegments.clear();
        }

        @Override
        public EmbeddingSearchResult<TextSegment> search(EmbeddingSearchRequest request) {
            throw new UnsupportedOperationException();
        }
    }

    private void createPdf(Path file, String text) throws IOException {
        try (PDDocument document = new PDDocument()) {
            PDPage page = new PDPage();
            document.addPage(page);
            try (PDPageContentStream contentStream = new PDPageContentStream(document, page)) {
                contentStream.beginText();
                contentStream.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA), 12);
                contentStream.newLineAtOffset(60, 700);
                contentStream.showText(text);
                contentStream.endText();
            }
            document.save(file.toFile());
        }

        try (PDDocument verify = Loader.loadPDF(file.toFile())) {
            assertEquals(1, verify.getNumberOfPages());
        }
    }

    private void createDocx(Path file, String text) throws IOException {
        try (XWPFDocument document = new XWPFDocument();
             OutputStream outputStream = Files.newOutputStream(file)) {
            document.createParagraph().createRun().setText(text);
            document.write(outputStream);
        }
    }

    private void createDoc(Path file) throws IOException {
        Files.write(file, Base64.getDecoder().decode(SIMPLE_DOC_BASE64));
    }

    private void createPptx(Path file, String title, String body) throws IOException {
        try (XMLSlideShow slideShow = new XMLSlideShow();
             OutputStream outputStream = Files.newOutputStream(file)) {
            XSLFSlide slide = slideShow.createSlide();
            XSLFTextBox titleBox = slide.createTextBox();
            titleBox.setAnchor(new java.awt.Rectangle(40, 40, 600, 80));
            titleBox.setText(title);

            XSLFTextBox bodyBox = slide.createTextBox();
            bodyBox.setAnchor(new java.awt.Rectangle(40, 150, 640, 200));
            bodyBox.setText(body);

            slideShow.write(outputStream);
        }
    }
}
